"use strict";

function moveNodeToParent(childSelector, parentSelector) {
  var prepend = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : false;
  var child = document.querySelector(childSelector);
  var parent = document.querySelector(parentSelector);
  if (!child || !parent) {
    return;
  }
  if (prepend) {
    parent.prepend(child);
    return;
  }
  parent.append(child);
}
function hideSearch() {
  var searchDropdown = document.querySelector('header .search-dropdown');
  if (!searchDropdown) {
    return;
  }
  searchDropdown.setAttribute('aria-hidden', 'true');
  searchDropdown.style.display = 'none';
}
function moveSearchMobile() {
  hideSearch();
  if (window.innerWidth < 1025) {
    moveNodeToParent('#before-navigation .before-navigation__inner', '#primary-menu-container', true);
    moveNodeToParent('#after-navigation .after-navigation__inner', '#primary-menu-container');
    moveNodeToParent('#search_modal .search-dropdown__content', '#primary-menu-container');
    return;
  }
  moveNodeToParent('#primary-menu-container .search-dropdown__content', '#search_modal', true);
  moveNodeToParent('#primary-menu-container .after-navigation__inner', '#after-navigation', true);
  moveNodeToParent('#primary-menu-container .before-navigation__inner', '#before-navigation', true);
}
function setHeaderHeight() {
  var siteHeader = document.querySelector('.site-header');
  if (!siteHeader) {
    return;
  }
  var headerHeight = siteHeader.offsetHeight;
  if (document.body.classList.contains('admin-bar')) {
    var adminBar = document.querySelector('#wpadminbar');
    headerHeight += adminBar ? adminBar.offsetHeight : 0;
  }
  document.documentElement.style.setProperty('--header-height', "".concat(headerHeight, "px"));
}
function setPageHeaderHeight() {
  var pageHeader = document.querySelector('.wp-block-cover.is-style-page-header');
  if (!pageHeader) {
    return;
  }
  if (window.innerWidth >= 600) {
    var headerGroup = pageHeader.querySelector('.wp-block-group');
    var headerGroupHeight = headerGroup ? headerGroup.offsetHeight : 0;
    pageHeader.style.paddingBottom = "".concat(headerGroupHeight / 2, "px");
    return;
  }
  pageHeader.style.paddingBottom = '';
}
function setupAnchorScrolling() {
  var links = document.querySelectorAll('a[href*="#"]:not([href="#"]):not([href="#0"]):not(.monitor-station-link)');
  links.forEach(function (link) {
    link.addEventListener('click', function (event) {
      var samePath = window.location.pathname.replace(/^\//, '') === link.pathname.replace(/^\//, '');
      var sameHost = window.location.hostname === link.hostname;
      if (!samePath || !sameHost || !link.hash) {
        return;
      }
      var target = document.querySelector(link.hash);
      if (!target) {
        target = document.querySelector("[name=\"".concat(link.hash.slice(1), "\"]"));
      }
      if (!target) {
        return;
      }
      event.preventDefault();
      var top = target.getBoundingClientRect().top + window.scrollY - 50;
      window.scrollTo({
        top: top,
        behavior: 'smooth'
      });
      setTimeout(function () {
        target.focus();
        if (document.activeElement === target) {
          return;
        }
        target.setAttribute('tabindex', '-1');
        target.focus();
      }, 450);
    });
  });
}
function positionPopover(trigger, popover) {
  var triggerRect = trigger.getBoundingClientRect();
  var top = triggerRect.bottom + window.scrollY + 8;
  var left = triggerRect.left + window.scrollX;
  popover.style.position = 'absolute';
  popover.style.display = 'block';
  popover.style.top = "".concat(top, "px");
  popover.style.left = "".concat(left, "px");
  popover.style.width = '300px';
  var popoverRect = popover.getBoundingClientRect();
  var overflowRight = popoverRect.right - window.innerWidth;
  if (overflowRight > 0) {
    popover.style.left = "".concat(Math.max(8, left - overflowRight - 8), "px");
  }
}
function hideAllPopovers() {
  document.querySelectorAll('.gpopover').forEach(function (popover) {
    popover.style.display = 'none';
  });
}
function setupPopovers() {
  var popoverTriggers = document.querySelectorAll('.info-popover');
  popoverTriggers.forEach(function (trigger) {
    trigger.addEventListener('click', function (event) {
      event.preventDefault();
      var popoverId = trigger.getAttribute('data-popover');
      if (!popoverId) {
        return;
      }
      var popover = document.getElementById(popoverId);
      if (!popover) {
        return;
      }
      var wasVisible = popover.style.display === 'block';
      hideAllPopovers();
      if (!wasVisible) {
        positionPopover(trigger, popover);
      }
    });
  });
  document.addEventListener('click', function (event) {
    var trigger = event.target.closest('.info-popover');
    var openPopover = event.target.closest('.gpopover');
    if (trigger || openPopover) {
      return;
    }
    hideAllPopovers();
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      hideAllPopovers();
    }
  });
}
function setupSearchToggle() {
  var searchLinks = document.querySelectorAll('#primary-menu .search-button a');
  var searchDropdown = document.querySelector('header .search-dropdown');
  if (!searchDropdown || !searchLinks.length) {
    return;
  }
  searchLinks.forEach(function (link) {
    link.addEventListener('click', function (event) {
      event.preventDefault();
      var hidden = searchDropdown.getAttribute('aria-hidden');
      if (hidden === 'false') {
        hideSearch();
        return;
      }
      var rect = link.getBoundingClientRect();
      var top = rect.top + window.scrollY + rect.height;
      var right = window.innerWidth - (rect.left + rect.width);
      searchDropdown.setAttribute('aria-hidden', 'false');
      searchDropdown.style.top = "".concat(top, "px");
      searchDropdown.style.right = "".concat(right, "px");
      searchDropdown.style.display = 'flex';
    });
  });
  document.addEventListener('click', function (event) {
    if (event.target.closest('.search-dropdown__close')) {
      hideSearch();
    }
  });
}
function setupPrintButtons() {
  document.querySelectorAll('.print-this-js').forEach(function (button) {
    button.addEventListener('click', function (event) {
      event.preventDefault();
      window.print();
    });
  });
}
function setupScrolledClass() {
  window.addEventListener('scroll', function () {
    document.body.classList.toggle('scrolled', window.scrollY > 0);
  });
}
if (document.location.hash) {
  setTimeout(function () {
    window.scrollTo(window.scrollX, window.scrollY - 50);
  }, 10);
}
document.addEventListener('DOMContentLoaded', function () {
  moveSearchMobile();
  setHeaderHeight();
  setPageHeaderHeight();
  setupAnchorScrolling();
  setupPopovers();
  setupPrintButtons();
  setupSearchToggle();
  setupScrolledClass();
  window.addEventListener('resize', function () {
    moveSearchMobile();
    setHeaderHeight();
    setPageHeaderHeight();
  });
});